import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"GroundShot: Visually Consistent Multi-Shot Long Video Generation via Entity-Grounded Shot Scheduling","description":"","frontmatter":{"title":"GroundShot: Visually Consistent Multi-Shot Long Video Generation via Entity-Grounded Shot Scheduling","arxiv":"2606.20799","date":"2026-06-18","authors":"Yixuan Lai, Tianjia Shao, Weijia Dou, Siyu Zhu, Jingdong Wang","categories":"cs.CV, cs.AI","topics":"智能体视频生成, 多镜头一致性, 实体级视觉记忆","outline":[2,2]},"headers":[],"relativePath":"papers/2606.20799.md","filePath":"papers/2606.20799.md","lastUpdated":null}'),l={name:"papers/2606.20799.md"};function e(i,s,m,r,c,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="groundshot-visually-consistent-multi-shot-long-video-generation-via-entity-grounded-shot-scheduling" tabindex="-1">GroundShot: Visually Consistent Multi-Shot Long Video Generation via Entity-Grounded Shot Scheduling <a class="header-anchor" href="#groundshot-visually-consistent-multi-shot-long-video-generation-via-entity-grounded-shot-scheduling" aria-label="Permalink to &quot;GroundShot: Visually Consistent Multi-Shot Long Video Generation via Entity-Grounded Shot Scheduling&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2606.20799" target="_blank" rel="noreferrer">2606.20799</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-06-18（v3: 2026-07-20）</td></tr><tr><td><strong>作者</strong></td><td>Yixuan Lai, Tianjia Shao, Weijia Dou, Siyu Zhu, Jingdong Wang</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>先算出「哪个镜头最适合当参照」并据此重排生成顺序，把生成结果里的角色/物体/场景抠出来质检，只把够格的写进受保护的 canonical 参照，让所有镜头都对着同一张参照生成，从而把链式误差传播换成星形结构。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/agentic">智能体视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>多镜头视频越长，反复出现的角色、物体、地点就越会偏离它们最初的样子。论文对这个现象给出了一个具体且可操作的观察：<strong>观众判断一致性的方式，是拿实体的每一次后续出现去比对它第一次清晰出现的样子</strong>，而这个初次出现的画质，就是后面所有镜头一致性的天花板。</p><p>这个观察直接推出一个结构性诊断。现有方法的一致性是<strong>链式</strong>的：后一镜依赖前一镜的帧、关键帧或帧级记忆，历史上下文里的错误会一路向前传播，最终导致显著的身份或场景漂移。而观众实际使用的标准是<strong>星形</strong>的：每一次出现都直接对着同一个 canonical 参照被评判，而不只是对着局部视觉上下文。把生成结构对齐到评判结构，就是这篇论文的整个立意。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>论文把已有方法分成架构级与流水线级，然后精确指出<strong>记忆类方法</strong>（StoryMem、VideoMemory、A²RD 等）才是最相关的对手，并给出两条批评。</p><p>第一，它们的记忆<strong>存取的是整帧</strong>，把实体解耦的任务甩给生成模型。当场景变复杂，模型要从混合的视觉上下文里推断出「这个角色应该长什么样」，可靠性迅速下降。</p><p>第二，<strong>生成顺序仍绑定在叙事顺序上</strong>。记忆可能从一个很早出现的弱视图被初始化——比如角色在一个宽景建立镜头里只占几十个像素——即使后面有一个中景特写能提供好得多的参照。后续镜头拿着这个几乎不含身份证据的参照做条件，约束太弱，一致性无从谈起。</p><p>论文还专门列了并发工作并划清界限：EntityBench 独立提出了实体级评测，A²RD 用 agentic refinement 做多镜头合成，IAMFlow 用 LLM 抽取的文本属性跨提示追踪身份。GroundShot 与它们的区别被表述得很清楚：不是沿一条会漂移的序列传播身份，而是用质量感知调度<strong>先建立高质量 canonical 参照</strong>，再让后续出现都对着同一个标准生成。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>只用已有背景：reference-conditioned 视频生成（Phantom、Vidu、Kling 一类）在<strong>给定参照</strong>的前提下已经能做到很强的镜内一致性；开放词表 grounding（GroundingDINO、ReferDINO）已经成熟；LLM 做剧本解析与共指消解是现成能力。</p><p>那么问题就不是「怎么让模型记住」，而是<strong>参照从哪来、用哪一张、什么时候去拿</strong>。这三个问句一旦提出来，答案几乎是被逼出来的：</p><p>参照从哪来——如果不要求用户提供参考图，就只能从模型自己生成的镜头里抠。但自生成的参照不都能用：一张被遮挡的脸、一个运动模糊的身影、一个只有背影的角色，携带的身份信息不足甚至具误导性。所以必须有质检门。</p><p>用哪一张——如果每次都用最近一次出现，就退回了链式传播。所以要有一个不被覆盖的锚。</p><p>什么时候去拿——如果按叙事顺序生成，锚就是第一次出现，而第一次出现未必清晰。既然锚的质量决定天花板，生成顺序就应该被<strong>重新调度</strong>，让最可能产出好参照的镜头先跑。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>链式一致性会累积误差，因为每一镜只对着上一镜负责；观众却是拿每一镜去比同一张「第一印象」。把生成结构改成同样的星形——先把最适合当第一印象的那个镜头生成出来、验证它、锁住它，再让所有镜头都对着它生成——误差就没有可累积的链条了。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>拿论文附录那个侦探剧本走一遍：Shot 1「Alex Chen，穿深色风衣的男侦探，走进警局大厅」；Shot 2「侦探坐在紧张的嫌疑人对面」；Shot 3「他走进雨夜的小巷」。</p><ol><li><strong>剧本解析</strong>。LLM 解析器一次读完整个剧本，建立全局实体集，定类型（character / object / location）并做跨镜共指——「Alex Chen」「the detective」「he」全部映射到 <code>char_alex</code>。同时抽取显式或强暗示的实体数量（「三个卫兵站在门口」→ 期望人数 3），并做<strong>全局上下文过滤</strong>：故事梗概只贡献风格与氛围，具体实体描述走逐镜实体图，避免第 5 镜才出场的蒙面骑手被梗概泄漏进第 2 镜。</li><li><strong>质量感知调度</strong>。对每个复现实体 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">e</span></span></span></span> 与它出现的每个镜头 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 预测参照质量分 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">src</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">e</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">Q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ref</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">e</span><span class="mpunct">;</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathcal" style="margin-right:0.0583em;">C</span><span class="mclose">)</span></span></span></span>，取最高者为源镜头，约束它先于该实体的其他镜头生成。所有约束构成有向图；不同实体的约束可能矛盾成环，解环时优先保留高优先级实体（角色 &gt; 物体 &gt; 地点）、预测收益更大、以及更接近叙事顺序的约束，再拓扑排序得到生成顺序 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span></span></span></span>。</li><li><strong>生成</strong>。构造分层提示（全局风格层 + 本镜实体层 + 镜头提示层），从记忆检索参照。无可用前景参照时走 T2V 自举，有则走 Ref2V：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8179em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span></span><span style="top:-3.35em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">~</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0001em;vertical-align:-0.2501em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0593em;">G</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0593em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight">m</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3281em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2501em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0738em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0738em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6891em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">m</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord text"><span class="mord">T2V</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">Ref2V</span></span><span class="mclose">}</span></span></span></span>。</li><li><strong>验证与修复</strong>。VLM critic 采帧比对镜头描述、所选参照与期望实体集，返回的不是标量而是<strong>结构化问题清单</strong>（实体数量错误、身份不符、服装不符、风格漂移、光照不一致、姿态不自然）。按问题类型定向修复：身份不符换更强或另一张参照；数量问题在改写提示里加显式计数与在场指令；风格光照漂移加强全局提示；严重伪影换 seed。重试预算内都不过就保留得分最高的那次。</li><li><strong>grounding 与入库</strong>。镜头被接受后用 ReferDINO 定位前景实体得到候选裁剪。地点走另一条路：把所有前景 ground 出来做并集掩码，交给指令式图像编辑模型抹除前景并重建背后场景。所有候选过类型化质检门 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">cand</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">c</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">e</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≥</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">type</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">e</span><span class="mclose">)</span></span></span></span>——角色查人脸可见性、正面度、清晰度；物体查可识别与无遮挡；地点查重建是否安全可复用。</li><li><strong>收尾</strong>。全部生成完毕后按叙事顺序重排回去。过程中同时维护一份<strong>生成经验</strong> <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.1464em;">X</span></span></span></span>，记录用了哪些参照、critic 报了什么问题、试过哪些修复及其成败，供后续镜头与后续运行复用。</li></ol><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>记忆维护的两道门是全文最关键的形式化。每个实体的第一个足够强的参照成为 canonical <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9357em;vertical-align:-0.247em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6887em;"><span style="top:-2.453em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">e</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∗</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span></span></span></span>，<strong>后续候选永不覆盖它</strong>，只能作为补充参照，且必须同时满足：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">sim</span></span><span class="mopen">(</span><span class="mord mathnormal">c</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7387em;"><span style="top:-2.453em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">e</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∗</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≥</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">id</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:1em;"></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">∧</span><span class="mspace" style="margin-right:1em;"></span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.5944em;vertical-align:-0.8444em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.4306em;"><span style="top:-2.3557em;margin-left:0em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mrel mtight">∈</span><span class="mord mtight"><span class="mord mathcal mtight">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1645em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight">e</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span></span></span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span><span class="mop">max</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.8444em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">sim</span></span><span class="mopen">(</span><span class="mord mathnormal">c</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≤</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">div</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span></span></p><p>两道门的分工很清楚。<strong>身份门</strong> <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">id</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 防止记忆整体从 canonical 漂走——这正是链式传播的病根，每一步都只与上一步相似，走一百步就可以离起点任意远；把每个新条目都直接与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9357em;vertical-align:-0.247em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6887em;"><span style="top:-2.453em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">e</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∗</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span></span></span></span> 比较，等于把「相似」这个非传递关系强制锚定在一个固定点上。<strong>多样性门</strong> <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">div</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 反向剔除近重复，只留下能补充新视觉证据的条目（角色主要是表情与大幅视角变化，地点主要是同一环境的不同相机方向或沿运动轨迹新露出的区域）。</p><p>附录给了具体阈值，读起来能看出设计意图：入库最低质量 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mop mtight"><span class="mtight">m</span><span class="mtight">i</span><span class="mtight">n</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.4</span></span></span></span>、角色人脸置信度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7719em;vertical-align:-0.136em;"></span><span class="mrel">≥</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.3</span></span></span></span>；冗余用 CLIP ViT-B/32 判定，余弦相似 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7719em;vertical-align:-0.136em;"></span><span class="mrel">≥</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.92</span></span></span></span> 直接拒绝；每镜每实体最多贡献 2 条，每实体最多保留 6 条（1 条 canonical + 5 条辅助）。而<strong>成为 canonical 的门槛高得多</strong>：质量分 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7719em;vertical-align:-0.136em;"></span><span class="mrel">≥</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.85</span></span></span></span>，角色还要人脸置信度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7719em;vertical-align:-0.136em;"></span><span class="mrel">≥</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.7</span></span></span></span> 且接近正面，地点要求重建无伪影、无残留前景。canonical 槽在满足条件前一直空着，此前的非 canonical 候选<strong>直接拒绝而不是先当辅助存着</strong>——这条设计确保锚点不会被将就的次品占据。</p><p>镜头验证的判据是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">pass</span></span><span class="mopen">(</span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span></span><span style="top:-3.35em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">~</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord mathnormal">Q</span><span class="mopen">(</span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span></span><span style="top:-3.35em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">~</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≥</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">pass</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">∧</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">¬</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">Severe</span></span><span class="mopen">(</span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span></span><span style="top:-3.35em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">~</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>：标量分数与严重问题的布尔谓词是<strong>合取</strong>关系，意味着一个高分但存在身份错配的镜头照样不通过。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>评测集为什么要重做</strong>？已有多镜头基准大多是整体性的：能说明一个方法不一致，说不清是哪个角色出了问题，也说不清是视角变化、遮挡、多身份混淆还是场景重访触发的。GroundBench 因此做成实体锚定 + 模块化：54 个剧本、309 个镜头、18 个子模块归入四个诊断轴（A 身份保持：尺度/光照/角度/时间间隔/遮挡；B 多身份区分：相似对/群体/角色-物体绑定/换装压力；C 结构模式：场景重访/平行时间线/长序列/晚期登场；D 鲁棒性探针：风格切换/人群消歧/代词共指），每子模块三个难度。指标由方法无关的 Unified Evaluation Detector 统一计算：每镜采 8 帧、ReferDINO 定位、有效人脸用 ArcFace 否则用 DINOv2。</p><p><strong>主结果</strong>（ARC / XCD / WCI）：GroundShot(Vidu) 0.426 / 0.157 / 0.264，HoloCine 0.368 / 0.119 / 0.212，StoryMem 0.314 / 0.125 / 0.240，MultiShotMaster-14B 0.282 / 0.078 / 0.204。增益集中在 ARC 与 XCD，对应「调度建立了更强的初次出现锚点」与「实体级 grounding 更好地分开了多个复现身份」。</p><p><strong>一个诚实的败点</strong>：StoryMem 的场景一致性 ESC 是 0.700，高于 GroundShot 的 0.670。论文没有回避而是给了解释——ESC 是掩掉前景后比对背景的 DINOv2 嵌入，整帧式记忆即使人脸与服装都漂了，依然能保住房间布局与光照。StoryMem 的 CSC 与 ESC 都强而 ARC/WCI 明显落后，恰好说明<strong>整体级指标会掩盖实体级失败</strong>。</p><p><strong>增益来自框架还是来自更强的后端？</strong> 这是最需要控制的混淆变量，论文的处理很扎实：三个后端（Vidu、Kling、Wan2.1+Phantom）各配一个 Naive 变体——同后端、按叙事顺序生成、用前一镜里最后一张含可见人脸的帧当参照。ARC 的对比是 0.346→0.426、0.355→0.414、0.301→0.376，三个后端一致提升，其中全开源的 Phantom 组也成立。</p><p><strong>消融</strong>（ARC / XCD / WCI / FaceSim，完整系统为 0.426 / 0.157 / 0.264 / 0.449）：去掉实体 grounding 掉得最狠（0.332 / 0.097 / 0.201 / 0.368，ARC −0.094、XCD −0.060、FaceSim −0.081）；去掉调度次之（0.355 / 0.141 / 0.210 / 0.415，ARC −0.071、WCI −0.054，而 FaceSim 只掉 0.034——说明调度主要改善的是<strong>锚点相对</strong>的评价而非平均两两相似度）；去掉 VLM 参照选择影响最小（0.411 / 0.149 / 0.250 / 0.439），论文解读为实体 grounding 本身已经提供了足够有区分度的参照。</p><p><strong>成本与人工评测</strong>：平均每个最终镜头 1.20 次视频生成调用，83.1% 一次通过；每剧本（约六镜）2.3 次 VLM 评审 + 3.4 次纯文本 LLM 调用。为排除「增益只是多生成几次换来的」，论文单独看了每镜只生成一次的 w/o Feedback &amp; Repair 变体（ARC 0.387），它仍优于所有外部基线——重试循环主要改善最坏情况鲁棒性。48 人、40 个剧本的人工评测里 GroundShot 拿到 4.18 / 4.23 / 4.21，HoloCine 为 3.62 / 3.76 / 3.68；文本对齐一项也领先（4.23 vs 3.76），说明实体锚定没有拿提示遵循去换一致性。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句版</strong>：观众按「第一次清晰出现」评判一致性，所以生成也该是星形而非链式；GroundShot 先预测每个镜头当参照的价值、据此把生成顺序从叙事顺序里解耦出来；参照从自生成的镜头里 ground 出来、过质检门后入库，第一个足够强的成为受保护的 canonical；训练无关、模型无关，在三个后端上相对各自的 Naive 变体一致提升 ARC；消融显示实体 grounding 与调度贡献了绝大部分增益，而每镜只生成一次的变体仍胜过全部外部基线。</p><p><strong>3 句版</strong>：多镜头一致性可以被重新表述为参照管理问题——哪张图当标准、什么时候去拿、怎么验证它够格。GroundShot 用质量感知调度 + 实体级 grounding + 受保护 canonical 参照把链式漂移换成星形约束。配套的 GroundBench 把整体一致性分解成可归因到具体实体与具体挑战维度的诊断。</p><p><strong>1 句版</strong>：先把最适合当参照的那个镜头拍出来，剩下的都对着它拍。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>canonical 参照一旦确立就<strong>永不被覆盖</strong>，并且所有后续候选都必须通过 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">sim</span></span><span class="mopen">(</span><span class="mord mathnormal">c</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6887em;"><span style="top:-2.453em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">e</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∗</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≥</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">id</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 才能入库。这套设计的隐含前提是：<strong>实体的身份在整个剧本中是时间不变的</strong>。</p><p>这个前提在很多真实叙事里不成立。角色换衣服、老去、受伤留疤、戴上面具——任何跨过 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">id</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 的<strong>有意改变</strong>都会被身份门当成不一致而拒绝，而需要这个新外观的后续镜头只能拿着过时的 canonical 去生成。系统在设计上无法区分「有意的改变」与「无意的漂移」，因为两者在相似度空间里长得一样。</p><p>问题出在<strong>证据的分布</strong>上。GroundBench 的四个诊断轴——A 轴变化的是尺度、光照、角度、时间间隔、遮挡；B 轴是多身份区分；C 轴是结构模式；D 轴是风格切换、人群、代词共指——全部属于 nuisance variation（干扰变量）或指代歧义，<strong>没有任何一个轴测试「剧本要求的外观改变」</strong>。也就是说，论文最强的证据恰好收集在它的假设成立的那个区域内。而并发的 CoTriSyGen 一线正是用显式可变的实体记忆去解决相反的问题（角色戴上假发后，后续镜头必须戴着假发），说明这个失效区间是真实存在且被同期研究认为重要的。</p><p>失效代价很高：一旦剧本包含有意的外观演进，GroundShot 的核心机制（锚点保护）会从「防漂移」直接翻转成「阻止剧情推进」。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>只验证调度这一个变量，跳过 grounding、验证与修复。</p><ul><li><strong>数据</strong>：GroundBench 的 A 模块 15 个剧本（身份保持轴，调度增益最直接）。</li><li><strong>实现</strong>：任意 Ref2V 接口。对照组是论文的 Naive 设定——按叙事顺序生成，用前一镜最后一张含可见人脸的帧当参照。实验组只改一件事：先用任意开源检测器估计每个镜头里主角的预期像素占比（或直接用 LLM 从镜头文本预测景别：特写 / 中景 / 全景 / 远景），把预期占比最大的镜头先生成，抠出裁剪作为所有其余镜头的参照。</li><li><strong>测量</strong>：ARC，锚点用人工挑选的参照帧而非「第一次有效出现」（见 §11 的理由）；同时报 FaceSim。</li><li><strong>判据</strong>：论文预测仅调度一项就值 +0.071 ARC。若重现出的增益接近这个量级，说明调度是可以独立成立的轻量改动；若 ARC 涨而 FaceSim 几乎不动（论文报的调度 FaceSim 只掉 0.034），则进一步印证调度改善的是锚点相对评价而非整体相似度。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>攻击 ARC 这个指标本身。</strong> ARC 的定义是「每个复现实体与它在最终叙事顺序中<strong>第一次有效检出</strong>的相似度均值」。GroundShot 的做法恰恰是刻意先生成画质最好的那个镜头，并把它的裁剪当作其余所有镜头的条件输入。当被优化的对象与被评价的锚点高度重合时，指标就带上了一层轻微的循环性——GroundShot 在做的事和 ARC 在测的事，比对基线而言更接近同一件事。</p><p>论文对此有两道防线，而且是正确的防线：方法无关的 UED（只读剧本与生成视频，不读方法侧的参照或调试裁剪），以及同后端的 Naive 对照（Vidu-Naive 0.346 → GroundShot 0.426）。但仍有一个更干净的检验没做：<strong>把 ARC 的锚点换成人工挑选的、与两种方法都无关的参照帧</strong>，再重算全部方法。若排序依然成立，循环性的质疑就被排除；若优势收缩，说明它优化的是「与自己选的锚点一致」而不是「与实体应有的样子一致」。这个实验成本很低，杀伤力却直指主指标。</p><p><strong>第二类反例：衣橱剧本。</strong> 构造一个第五模块——角色在故事中途有意改变外观并在后期恢复（第 3 镜穿上大衣，第 6 镜脱下）。可预测的结果是 GroundShot 的 ARC <strong>依然很高</strong>，因为它会稳定地渲染 canonical 那身装扮；但文本对齐会崩，因为剧本明确要求了改变。这个设计的精妙之处在于：<strong>指标恰好奖励了失败</strong>。它同时暴露了方法的假设边界（§9）与 GroundBench 覆盖面的缺口，且不需要任何新模型，只需要新剧本。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：记忆里每个实体只有「一个受保护的 canonical + 至多五条辅助」，这是一个<strong>无时间维度</strong>的集合。它能表达「同一个人从不同角度看」，不能表达「同一个人在故事的不同时刻」。</p><p><strong>新 framing</strong>：把实体身份从「一张受保护的图」升级为「一条带版本的状态时间线」。每个实体有一个基础身份，加上一串已提交的状态变更（<code>Alex@v0</code> → <code>Alex@v1</code> 淋雨后自 shot 3 起 → <code>Alex@v2</code> 换装后自 shot 6 起），每个镜头显式声明它读取哪个版本。身份门不再对全局唯一的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9357em;vertical-align:-0.247em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6887em;"><span style="top:-2.453em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">e</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∗</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span></span></span></span> 生效，而是<strong>在版本内</strong>生效：段内保持严格锚定，段间允许剧本授权的跳变。这让「有意改变」与「无意漂移」第一次在表示层被区分开——当前的 GroundShot 与 CoTriSyGen 各自只解决了其中一半。</p><p><strong>可借鉴的邻域工具</strong>：版本控制系统的分支与合并语义、数据库的多版本并发控制与时间旅行查询——它们处理的正是「同一实体的多个版本共存、每次读取必须指明时刻」这个同构问题；一致性检查则可以借用编译器里的到达定义分析（哪个赋值到达了这次使用）。</p><p><strong>第一个实验</strong>：给 GroundBench 加一个第五模块（约 12 个剧本），每个剧本包含一次剧本授权的外观改变与一次可选恢复，改变发生的镜号固定以便分组评测。在这个模块上比较三种记忆：(a) 论文的 canonical-only；(b) 完全可变、以最新观测为准的记忆；(c) 版本化时间线。度量两项而不是一项——<strong>段内 ARC</strong>（同一版本区间内的锚点相对一致性）与<strong>变更合规率</strong>（剧本要求的改变是否真的出现在画面里）。当前所有方法都只被第一项衡量过，而真实创作同时需要两项。</p>',56)])])}const d=a(l,[["render",e]]);export{o as __pageData,d as default};
